"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[1424],{40355:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>d,frontMatter:()=>o,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"getting-started/concepts","title":"Concepts","description":"Before diving deep into the architecture and mechanisms of rollups, it\'s important to understand the fundamental concepts behind these scalability solutions. Rollups play a crucial role in enhancing blockchain performance by moving computation off-chain while ensuring security through on-chain verification. This section covers the core principles of rollups, the different approaches to validating state updates, and how dispute resolution mechanisms function. These foundational ideas will help you better grasp the architecture and innovations introduced by Cartesi\'s rollup solutions, including the Dave fraud-proof system.","source":"@site/cartesi-rollups_versioned_docs/version-2.0/getting-started/concepts.md","sourceDirName":"getting-started","slug":"/getting-started/concepts","permalink":"/docs/cartesi-rollups/2.0/getting-started/concepts","draft":false,"unlisted":false,"editUrl":"https://github.com/cartesi/docs/tree/main/cartesi-rollups_versioned_docs/version-2.0/getting-started/concepts.md","tags":[],"version":"2.0","lastUpdatedAt":1780953838000,"frontMatter":{"id":"concepts","title":"Concepts","resources":[{"url":"https://cartesi.io/blog/understanding-cartesi-rollups-pt2/","title":"Understanding Cartesi Rollups"},{"url":"https://github.com/cartesi/dave","title":"Dave"}]}}');var s=n(74848),a=n(28453);const o={id:"concepts",title:"Concepts",resources:[{url:"https://cartesi.io/blog/understanding-cartesi-rollups-pt2/",title:"Understanding Cartesi Rollups"},{url:"https://github.com/cartesi/dave",title:"Dave"}]},r=void 0,l={},c=[{value:"What is a Blockchain Rollup?",id:"what-is-a-blockchain-rollup",level:2},{value:"Zero-knowledge Rollups (ZK Rollups)",id:"zero-knowledge-rollups-zk-rollups",level:3},{value:"Optimistic Rollups (ORs)",id:"optimistic-rollups-ors",level:3},{value:"Introducing Dave \u2014 an interactive fraud-proof system",id:"introducing-dave--an-interactive-fraud-proof-system",level:2}];function h(e){const t={a:"a",em:"em",h2:"h2",h3:"h3",li:"li",ol:"ol",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(t.p,{children:["Before diving deep into the architecture and mechanisms of rollups, it's important to understand the fundamental concepts behind these scalability solutions. Rollups play a crucial role in enhancing blockchain performance by moving computation off-chain while ensuring security through on-chain verification. This section covers the core principles of rollups, the different approaches to validating state updates, and how dispute resolution mechanisms function. These foundational ideas will help you better grasp the architecture and innovations introduced by Cartesi's rollup solutions, including the ",(0,s.jsx)(t.strong,{children:"Dave"})," fraud-proof system."]}),"\n",(0,s.jsx)(t.h2,{id:"what-is-a-blockchain-rollup",children:"What is a Blockchain Rollup?"}),"\n",(0,s.jsx)(t.p,{children:'A rollup is a blockchain scalability solution that offloads complex computations "off-chain," meaning they run on a separate computing environment (execution layer) outside the base layer, such as Ethereum.'}),"\n",(0,s.jsx)(t.p,{children:"When employing rollups, the blockchain receives and logs transactions. In rare instances of an active attack or the involvement of a malicious agent, parties may disagree with a computation\u2019s outcomes, and the blockchain will resolve these disputes. However, it's important to note that disagreements are not expected to occur under normal circumstances."}),"\n",(0,s.jsx)(t.p,{children:"Users interact with a rollup through transactions on the base layer. They send messages (inputs) to the rollup on-chain smart contracts to define a computation to be processed and, as such, advance the state of the computing environment on the execution layer. Interested parties run an off-chain component (a node on the execution layer) that watches the blockchain for inputs, understanding, and executing the state updates."}),"\n",(0,s.jsx)(t.p,{children:"Once in a while, the state is checkpointed on the chain; at this point, it is considered finalized and can thus be accepted by any smart contract on the base layer."}),"\n",(0,s.jsx)(t.p,{children:"Ensuring this operation is secure is vital, meaning that the execution layer node must somehow prove the new state to the base layer."}),"\n",(0,s.jsxs)(t.p,{children:["Consider this question: ",(0,s.jsx)(t.em,{children:'"How does Ethereum know that the data posted by an off-chain L2 node is valid and was not submitted maliciously?"'})]}),"\n",(0,s.jsx)(t.p,{children:"The answer depends on the rollup implementation, which falls within one of two categories according to the type of proof used:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Zero-knowledge Rollups (ZK Rollups)"}),", which use validity proofs."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Optimistic Rollups (ORs)"}),", which use fraud proofs."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h3,{id:"zero-knowledge-rollups-zk-rollups",children:"Zero-knowledge Rollups (ZK Rollups)"}),"\n",(0,s.jsx)(t.p,{children:"In ZK rollups, which use validity proof schemes, every state update is accompanied by a cryptographic proof created off-chain, attesting to its validity. The update is only taken if the proof successfully passes verification on-chain. Validity proofs(ZK Rollups) bring the enormous benefit of instant finality\u2014as soon as a state update appears on-chain, it can be fully trusted and acted upon."}),"\n",(0,s.jsx)(t.p,{children:"The choice, however, also brings less than ideal properties: generating ZK proofs for general-purpose computations is, when possible, immensely expensive, and each on-chain state update must pay the extra gas fee for including and verifying a validity proof."}),"\n",(0,s.jsx)(t.h3,{id:"optimistic-rollups-ors",children:"Optimistic Rollups (ORs)"}),"\n",(0,s.jsxs)(t.p,{children:["Optimistic Rollups, which use fraud-proof schemes, work by a different paradigm. State updates come unaccompanied by proofs; they\u2019re proposed and, if not challenged, confirmed on-chain. Challenging a state update proposal using fraud proofs has two categories: ",(0,s.jsx)(t.strong,{children:"non-interactive"})," and ",(0,s.jsx)(t.strong,{children:"interactive"}),"."]}),"\n",(0,s.jsx)(t.p,{children:"Non-interactive refers to the fact that the challengers can prove that a state update is invalid in one step. With interactive fraud proofs, the claimer and challenger must, mediated by the blockchain, partake in something similar to a verification game."}),"\n",(0,s.jsx)(t.p,{children:"The assumption that state updates will likely be honest often gives solutions like this the name of Optimistic Rollups."}),"\n",(0,s.jsx)(t.p,{children:"This optimism is reinforced by financial incentives that reward honest behavior. Furthermore, any proposed false state will only be accepted if it remains undisputed for a prolonged period."}),"\n",(0,s.jsx)(t.p,{children:"The main advantage of Optimistic Rollups is that they are much cheaper than ZK Rollups. Posting a state update on-chain is minimal, and challenging a state update is also low."}),"\n",(0,s.jsx)(t.p,{children:'The main disadvantage is that state updates take time to finalize and are not entirely accepted immediately. During this period, they are considered "optimistic" and can be challenged.'}),"\n",(0,s.jsx)(t.h2,{id:"introducing-dave--an-interactive-fraud-proof-system",children:"Introducing Dave \u2014 an interactive fraud-proof system"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.a,{href:"https://github.com/cartesi/dave",children:"Dave"})," is Cartesi's dispute resolution algorithm designed to address shortcomings in existing fraud-proof protocols. Traditional fraud-proof systems often face challenges such as delay attacks and vulnerability to Sybil attacks, where malicious nodes can disrupt operations by continuously challenging transactions or overwhelming honest validators."]}),"\n",(0,s.jsx)(t.p,{children:"Dave introduces an approach where the resources required to defend against disputes grow logarithmically with the number of opponents. This means that defending against challenges remains affordable for a single honest node, even in the face of multiple attackers."}),"\n",(0,s.jsxs)(t.p,{children:["With Dave, a single honest participant can effectively defend their claims on-chain, ensuring the integrity of transactions without relying on trust in validators. Based on the ",(0,s.jsx)(t.a,{href:"https://arxiv.org/abs/2212.12439",children:"Permissionless Refereed Tournaments algorithm"}),", this protocol empowers anyone to validate rollups and uphold correct states on-chain, enhancing transaction security and reliability."]}),"\n",(0,s.jsx)(t.p,{children:"Similar to how a consensus algorithm is crucial for achieving agreement on a single state of the blockchain among all nodes in a base-layer chain, Dave plays a fundamental role in ensuring the integrity and trustworthiness of state transitions within Cartesi Rollups."})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var i=n(96540);const s={},a=i.createContext(s);function o(e){const t=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);